SELECT fhir_Slot.Id, fhir_Slot.Status, fhir_Slot.StartTime, fhir_Slot.EndTime, fhir_Schedule.PractitionerReference FROM fhir_Slot INNER JOIN fhir_Schedule ON fhir_Slot.ScheduleReference = fhir_Schedule.Id WHERE fhir_Schedule.PractitionerReference = @practitionerRef AND fhir_Slot.Status = 'free' AND fhir_Slot.StartTime >= @fromDate AND fhir_Slot.StartTime < @toDate ORDER BY fhir_Slot.StartTime 